const labelType = (t) => LABELS.type[t] || t || LABELS.empty;
const labelStatus = (s) => LABELS.status[s] || s || LABELS.empty;
const labelCategory = (value) => (!value || value === 'Uncategorized' ? LABELS.uncategorized : value);
const labelReviewReason = (code) => LABELS.reviewReason[code] || code;
const labelReviewFlag = (f) => LABELS.reviewFlag[f] || 'teks mencurigakan';
const labelJobError = (e) => (e ? (LABELS.jobError[e] || String(e).replaceAll('_', ' ')) : LABELS.jobError.none);
